effect.shader:
vec4 gmBokeh(sampler2D tex,vec2 uv,vec2 size,float radius,float phase){vec4 sum=vec4(0.0);float w=0.0;for(int i=0;i<16;i++){float a=6.2831853*(float(i)/16.0+phase);float r=radius*(0.35+0.65*fract(float(i)*0.618));float k=1.0+0.35*bokehShape*cos(a*6.0);sum+=texture2DCv(tex,clamp(uv+vec2(cos(a),sin(a))*r*k/size,0.0,1.0));w+=1.0;}return sum/w;}
void main(){vec2 uv=acScreenNorm;float c=cos(angle),s=sin(angle);float axis=dot(uv-0.5,vec2(c,s))+0.5;float edge=mix(-softness,1.0+softness,progress);float mask=1.0-smoothstep(edge-softness,edge+softness,axis);float focus=sin(clamp(progress,0.0,1.0)*3.14159265);vec2 size=max(acScreenSize,vec2(1.0));
vec4 a=gmBokeh(inputImg.texture,uv,size,blurPx*focus,0.0),b=gmBokeh(comp.texture,uv,size,blurPx*focus,0.17);vec2 ca=vec2(chromatic/size.x,0.0)*focus;
a.r=texture2DCv(inputImg.texture,clamp(uv+ca,0.0,1.0)).r;b.b=texture2DCv(comp.texture,clamp(uv-ca,0.0,1.0)).b;gl_FragColor=mix(a,b,mask);}
